# Inside res://scenes/table/table.gd:
func _on_draw_pressed() -> void:
    if TurnManager.current_player_index != 0:
        return
    staged_cards.clear()
    if GameState.penalty_stack > 0:
        var picked: int = GameState.penalty_stack
        GameState.draw_cards(0, picked)
        GameState.penalty_stack = 0
        status_label.text = "You picked up %d penalty cards." % picked
    else:
        GameState.draw_cards(0, 1)
        status_label.text = "You drew 1 card."
    TurnManager.advance_turn()

func _on_play_selected_pressed() -> void:
    if TurnManager.current_player_index != 0 or staged_cards.is_empty():
        return
    var card: CardData = staged_cards[0]
    var top: CardData = GameState.top_discard()
    if RuleValidator.is_single_card_playable(card, top, GameState.penalty_stack, GameState.declared_suit):
        _commit_single_card_play(0, card)
        staged_cards.clear()
    else:
        staged_cards.clear()
        GameState.draw_cards(0, 1)
        status_label.text = "Invalid play! Penalty card drawn."
        TurnManager.advance_turn()

