practicePrompt.solutionCode:
func has_playable_card(player: int) -> bool:
    var top: CardData = GameState.top_discard()
    for card in GameState.hands[player]:
        if RuleValidator.is_single_card_playable(card, top, GameState.penalty_stack, GameState.declared_suit):
            return true
    return false

